    console.assert(JSON.stringify(candidate([0,0,0,0,0], 0, 0)) === JSON.stringify([0, 0]));
    console.assert(JSON.stringify(candidate([10,20,30,40,50], 1, 25)) === JSON.stringify([0, 3]));
    console.assert(JSON.stringify(candidate([0,0,0,0], 3, 1)) === JSON.stringify([-1, -1]));
    console.assert(JSON.stringify(candidate([0,0,0,0], 1, 1)) === JSON.stringify([-1, -1]));
    console.assert(JSON.stringify(candidate([10,5,15,20,25], 2, 10)) === JSON.stringify([1, 3]));
    console.assert(JSON.stringify(candidate([4,2,3,1,5], 1, 2)) === JSON.stringify([0, 1]));
    console.assert(JSON.stringify(candidate([1,3,5,7,9], 3, 4)) === JSON.stringify([0, 3]));
    console.assert(JSON.stringify(candidate([45,46,47,48,49,50], 2, 5)) === JSON.stringify([0, 5]));
    console.assert(JSON.stringify(candidate([4,2,3,4,5], 1, 2)) === JSON.stringify([0, 1]));
